INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tgweb_english', '長文問題', 'ヴァーティカルファーミング（垂直農業）', 'Vertical farming, the practice of growing crops in stacked layers under artificial light, has expanded rapidly in cities over the past decade. Unlike traditional agriculture, vertical farms do not depend on soil quality, seasonal weather, or large tracts of land, which makes them attractive in urban areas where space is limited and transportation costs for fresh produce are high. Because crops are grown indoors, water use can also be reduced significantly compared with open-field farming.

Dr. Elena Marsh leads a research team studying how vertical farming affects crop nutrition. Her team compares vegetables grown in vertical farms with those grown using conventional methods, measuring differences in vitamin content, growth speed, and water efficiency. When Marsh’s team began this research in 2016, only a handful of cities had commercial vertical farms in operation. Today, more than 200 such farms exist worldwide, and Marsh’s data has been used by several companies to improve their growing conditions.

One of the biggest challenges Marsh’s team identified was energy use, since artificial lighting requires substantial electricity. In 2019, an engineer on her team, Daniel Cho, proposed a system that adjusts light intensity and color throughout the day based on each plant’s specific growth stage, rather than using constant lighting. This adaptive system reduced energy consumption at test farms by nearly 30 percent while maintaining crop yields, and it has since been adopted by several vertical farming companies.

Marsh believes that reducing energy costs is essential if vertical farming is to become widely affordable rather than a niche method used only by large corporations. Her team is now testing whether combining adaptive lighting with small-scale solar panels could make individual vertical farms nearly self-sufficient in terms of energy. If successful, Marsh hopes the technology could eventually be scaled down for use in schools and community centers, allowing more people to grow fresh food regardless of local climate or available land.

【設問】
What is one advantage of vertical farming mentioned in the passage?', NULL, '["It requires more land than traditional farming.","It does not depend on soil quality or seasonal weather.","It always produces more nutritious vegetables than field farming.","It eliminates the need for any electricity."]', 1, '["第1段落「土壌や天候に依存しない」。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型英語: 長文問題・サイエンス時事編）', 911);
