INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tgweb_english', '長文問題', '食品廃棄削減の技術', 'Food waste has drawn increasing attention as both an environmental and economic issue, with a significant portion of food produced worldwide never reaching consumers due to spoilage, inefficient supply chains, or oversupply at retail level. Reducing this waste has become a priority for researchers seeking practical solutions that can be applied at various points in the food supply chain, from farms to grocery stores.

Dr. Wei Zhang has focused her research on extending the shelf life of fresh produce without relying on artificial preservatives, which some consumers prefer to avoid. Her team studies natural coatings, thin protective layers applied to fruits and vegetables, that slow moisture loss and reduce exposure to oxygen, both of which contribute to spoilage. When Zhang began this research in 2015, most available coatings were either ineffective at meaningfully extending shelf life or left a noticeable residue that affected taste.

In 2020, a food scientist on Zhang’s team, Rosa Fernandez, developed a coating derived from plant-based cellulose that extended the shelf life of certain fruits by up to two weeks without altering their taste or appearance, a substantial improvement over earlier coatings tested by the team. This innovation attracted attention from several large grocery chains interested in reducing spoilage-related losses.

Zhang’s team is now working to adapt the coating for a wider range of produce types, since different fruits and vegetables lose moisture and spoil through somewhat different processes. She notes that even modest reductions in spoilage could meaningfully lower both food waste and grocery prices if adopted widely across the supply chain. Zhang hopes that within the next several years, coatings like the one her team developed could become a standard, low-cost tool used throughout the produce industry to reduce waste from farm to store shelf.

【設問】
Why has food waste drawn increasing attention?', NULL, '["Because it is both an environmental and economic issue.","Because all food produced worldwide is wasted.","Because consumers prefer wasted food over fresh food.","Because grocery stores no longer sell fresh produce."]', 0, '["第1段落「環境的にも経済的にも問題」。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型英語: 長文問題・サイエンス時事編）', 917);
