INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tgweb_english', '長文問題', '宇宙ゴミ（スペースデブリ）対策', 'Space debris, consisting of defunct satellites, spent rocket stages, and fragments from past collisions, has steadily accumulated in Earth’s orbit since the beginning of space exploration. As the number of satellites launched each year continues to grow, driven partly by demand for global internet coverage, concerns about collisions between debris and functioning spacecraft have become more pressing among researchers and space agencies alike.

Dr. Viktor Andreev leads a team developing technology to track and eventually remove hazardous debris from crowded orbital regions. His team uses ground-based radar combined with orbital sensors to catalog debris fragments as small as a few centimeters, which are too small to track using older radar systems but still large enough to seriously damage a satellite in a high-speed collision. When Andreev’s project began in 2016, tracking systems could reliably detect only larger fragments, leaving many smaller but still dangerous pieces unaccounted for.

In 2021, an engineer on Andreev’s team, Sophie Lindqvist, helped design a small satellite equipped with a robotic arm capable of capturing selected debris fragments and guiding them toward Earth’s atmosphere, where they would burn up safely upon reentry. Early tests of this system successfully captured and removed several defunct satellite components from crowded orbital paths, demonstrating that active debris removal was technically feasible, not just theoretical.

Andreev acknowledges that removing all existing debris is currently far too costly and slow to be realistic, so his team prioritizes objects posing the greatest collision risk to active satellites. He is now working with international space agencies to establish shared guidelines for debris removal priorities, since orbital debris crosses national boundaries and affects satellites operated by many different countries. Andreev hopes that international cooperation, combined with improving removal technology, can prevent orbital regions from becoming too dangerous for continued satellite use.

【設問】
Why have concerns about space debris become more pressing recently?', NULL, '["Because the number of satellites launched each year continues to grow.","Because all space exploration has stopped completely.","Because debris no longer poses any risk to satellites.","Because radar systems can no longer detect any debris."]', 0, '["第1段落「衛星打ち上げ数の増加」。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型英語: 長文問題・サイエンス時事編）', 918);
